/**
 * Types generated by hand from docs/DATA_CONTRACTS.md.
 *
 * DATA_CONTRACTS.md is the ONLY coupling between the pipeline and the
 * frontend. Both sides code against it and nothing else, which is what lets
 * them proceed in parallel. If a field here disagrees with that document, the
 * document wins and this file is wrong.
 */

export type Stage = "SUSPECTED" | "CORROBORATED" | "CONFIRMED" | "UNREPORTED";

export type BaselineQuality = "good" | "sparse" | "insufficient" | "unavailable";

export type CorroborationType =
  | "independent_cross_sensor"
  | "adjacent_layer"
  | "same_plane_persistence"
  | "single_sensor";

/**
 * Which counter a write incremented.
 *
 * Note the spelling: `external_timer` with an underscore is the COUNTER KEY.
 * The workflow input value is `external-timer` with a hyphen. The pipeline maps
 * one to the other in exactly one place, and the frontend only ever sees the
 * counter key.
 */
export type TriggerKind = "schedule" | "external_timer" | "manual";

/** Which trigger is actually armed, which decides the cadence the page states. */
export type TriggerMode = "external_timer" | "schedule_only";

export type Heartbeat = {
  /**
   * GitHub's run counter across ALL triggers. It is not a count of scheduled
   * runs, and the page must never label it as one. Label it "Run".
   */
  run_number: number;
  written_at: string;
  source_commit: string;
  /** `github.event_name`: `schedule` or `workflow_dispatch`. */
  triggered_by: string;
  /**
   * A CLAIM, passed as a workflow_dispatch input. GitHub cannot tell the Worker
   * from a person running curl, because the sender is the same token owner. The
   * page must present this as a claim, never as proof.
   */
  dispatch_source: string | null;
  /** The checkable half: what the timer said against when the run wrote. */
  dispatch_scheduled_for: string | null;
  dispatch_lag_seconds: number | null;
  expected_cadence_minutes: number;
  /** The pipeline owns the staleness decision. The page only reports it. */
  stale_after_minutes: number;
  trigger_mode: TriggerMode;
  /**
   * THE ONE AUTHORITATIVE COUNTER. Every other count is derived from this.
   * The previous attempt stored two counters, they disagreed, and the page
   * ended up denying a criterion it had already met.
   */
  writes_by_trigger: Record<TriggerKind, number>;
  first_unassisted_write: string | null;
  last_unassisted_write: string | null;
};

export type Meta = {
  generated_at: string;
  pipeline_version: string;
  runs: Record<
    string,
    {
      last_success: string;
      status: string;
      note?: string;
      expected_cadence_minutes: number;
      /** Satellite acquisition time of the newest record. Not the run time. */
      data_as_of: string;
    }
  >;
  counts: {
    total_active: number;
    shown: number;
    by_stage: Partial<Record<Stage, number>>;
  };
  latency: {
    /** Until this is true, the page claims no latency at all. */
    measured: boolean;
    observation_to_publish_minutes_p50: number | null;
    note?: string;
  };
  baseline_version: string;
  corroboration_mode: "full" | "degraded";
};

export type EventProperties = {
  event_id: string;
  event_type: string;
  family: string;
  stage: Stage;
  severity: number;
  /**
   * A number, or null when the baseline could not score the event. The
   * frontend must render null as "not scored", NEVER as 0 and never as blank:
   * 0 means "exactly average", which is a different claim entirely.
   */
  sigma: number | null;
  baseline_quality: BaselineQuality;
  corroboration_type: CorroborationType;
  first_detected: string;
  last_detected: string;
  is_active: boolean;
  bbox: [number, number, number, number];
  area_km2: number;
  /**
   * The cell containing the event's current centroid. Mutable, and allowed to
   * differ from the cell frozen inside `event_id`. Use THIS for any geographic
   * query or display, never the id.
   */
  h3_r5_current: string;
  /** False for all SUSPECTED. The pipeline owns this decision, not the client. */
  interactive: boolean;
  inside_protected_area: boolean;
  intersects_species_range: boolean;
};

export type EventFeature = {
  type: "Feature";
  geometry: { type: "Point"; coordinates: [number, number] };
  properties: EventProperties;
};

export type LiveEvents = {
  type: "FeatureCollection";
  generated_at: string;
  pipeline_version: string;
  features: EventFeature[];
};
